import * as React from "react";

export type VinylSleeveIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function VinylSleeveIcon({ size = 20, ...props }: VinylSleeveIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="14" height="16" rx="1.5" /><circle cx="18" cy="12" r="5" /><circle cx="18" cy="12" r="1.2" />
    </svg>
  );
}
